// Ping IndexNow (Bing, Yandex, Seznam, Naver…; Google ignores it) with every URL in the sitemaps.
// node scripts/indexnow.js            -> all URLs from the live sitemap index
// node scripts/indexnow.js /merge-pdf/ /compress-pdf/   -> only these paths
// Only works on the final custom domain (key file https://DOMAIN/<key>.txt is generated by the build).
const site=require('../src/site.json');const B=(process.env.SITE_URL||site.baseUrl).replace(/\/+$/,'');const host=new URL(B).host;
(async()=>{let urls=process.argv.slice(2).map(p=>B+p);
 if(!urls.length){const idx=await (await fetch(B+'/sitemap.xml')).text();for(const sm of idx.match(/<loc>[^<]+<\/loc>/g).map(x=>x.slice(5,-6))){const x=await (await fetch(sm)).text();urls.push(...x.match(/<loc>[^<]+<\/loc>/g).map(y=>y.slice(5,-6)));}}
 const k=await fetch(`${B}/${site.indexNowKey}.txt`);if(!k.ok||(await k.text()).trim()!==site.indexNowKey){console.error('key file not reachable at',`${B}/${site.indexNowKey}.txt`);process.exit(1);}
 for(let i=0;i<urls.length;i+=10000){const r=await fetch('https://api.indexnow.org/indexnow',{method:'POST',headers:{'Content-Type':'application/json; charset=utf-8'},body:JSON.stringify({host,key:site.indexNowKey,keyLocation:`${B}/${site.indexNowKey}.txt`,urlList:urls.slice(i,i+10000)})});console.log('IndexNow',r.status,r.statusText,urls.slice(i,i+10000).length,'URLs');}})();
